SELECT table,name,type FROM system.columns WHERE database='system' AND table IN ('asynchronous_metric_log','metric_log') AND (name IN ('event_time','event_date','metric','value') OR name ILIKE '%BackgroundMerges%') ORDER BY table,name LIMIT 100 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames
